SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==========================================================================================
-- This procedure was automatically generated by Insikt Studio.
-- Any edits can and will be overwritten.
-- ==========================================================================================
CREATE procedure [app].[IncUpdate_EventHandler]
(
    @JobID int
    ,@Type nvarchar(4000) = 'IncUpdate'
    ,@ParamList nvarchar(4000) = null 
    ,@ParentEventID int = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount
  
  
begin try
    --------------------------------------------------------------------------
    -- Start
    --------------------------------------------------------------------------
    declare 
		@LogMessage nvarchar(max)
		,@ErrorMessage nvarchar(max)
	
    select
        @LogMessage = 'JobID = ' + isnull(CAST(@JobID as nvarchar(max)), 'NULL')
    exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
            ,@EventTitle = 'Handle Planning IncUpdate Events'
            ,@Description = @LogMessage
  	
  
    declare
        @EventPrio int
        ,@EventID int     
        ,@TriggerQuery nvarchar(max)
        ,@CalcProc nvarchar(max)
        ,@PostEventBatchProcedure nvarchar(max)
        ,@DynSQL nvarchar(max)
        ,@MaxIncUpdateID bigint
  
  
    create table #EventIncUpdate
    (
        EventID int not null
        ,ID bigint
    )
    create clustered index tmp_IX_EventIncUpdate on #EventIncUpdate(EventID, ID)
  
    create table #IncUpdate
    (
        ID bigint
    )
    create clustered index tmp_IX_IncUpdate on #IncUpdate(ID)
  
  
    create table #TriggeredEvents
    (
        TriggerOrder int not null identity(1,1) primary key   
        ,EventID int not null
        ,MaxIncUpdateID bigint
        ,PostEventBatchProcedure nvarchar(1024)
    )
     declare 
		@TriggerOrderIterator int = 1
		,@TriggerOrderIteratorMax int = null

  

    select @EventPrio = MAX(EventPrio) from [app].IncUpdate_EventConfiguration where JobID = @JobID and IsDisabled = 0
    while @EventPrio is not null and not exists(select 1 from #TriggeredEvents)
        begin
            --
            -- Kontrollera samtliga event med denna prio-nivå
            --			
			set @DynSQL = null
			;with EventOrder as
			(
				select
					Iterator = row_number() over (order by e.EventOrder, e.EventID)
					,EventID = e.EventID
					,TriggerQuery = tq.TriggerQuery
					,TriggerProcedure = tq.TriggerProcedure
				from
					[app].IncUpdate_EventConfiguration e
						left join [app].IncUpdate_EventConfiguration_TriggerQueryView tq on
							tq.EventID = e.EventID
				where
					e.EventPrio = @EventPrio
					and e.JobID = @JobID
					and e.IsDisabled = 0
			)
			select
				@DynSQL = 
					isnull
					(
						N'insert into #EventIncUpdate(EventID, ID)' 
						+
						(
							select iif(row_number() over (order by e.Iterator) > 1, N'
'								+ N'union all ', N'')
								+ N'select EventID = ' + cast(e.EventID as nvarchar(max)) + N', e.ID from (' + e.TriggerQuery + N') e(ID)'
							from
								EventOrder e
							where
								e.TriggerQuery <> ''
							order by 
								e.Iterator
							for xml path, type
						).value(N'.[1]', N'nvarchar(max)')
						+ N';'
					,N''
					)
					+
					isnull
					(
					N'declare @ProcResult int;
' 
					+
					(
						select 
							+ N'exec @ProcResult = ' + e.TriggerProcedure + N';
'							+ N'if @ProcResult > 0 insert into #EventIncUpdate(EventID, ID) values (' + cast(e.EventID as nvarchar(max)) + N', @ProcResult)'
						from
							EventOrder e
						where
							e.TriggerProcedure <> ''
						order by 
							e.Iterator
						for xml path, type
					).value(N'.[1]', N'nvarchar(max)')
					,N''
					)	
			begin try
				exec (@DynSQL)
			end try
			begin catch
				select @ErrorMessage = app.GetErrorMessage();
				raiserror('Error executing dynamic SQL "%s" for event id %i, Error: %s', 16, 10
					,@DynSQL
					,@EventID							
					,@ErrorMessage);
			end catch


			

			--
			-- Kontrollera om ett eller flera event med denna prio har triggats 
			--
			if exists(select 1 from #EventIncUpdate)
				begin
					--	
					-- Japp, event har triggats.
					--
					insert into #TriggeredEvents
					(
						EventID
						,MaxIncUpdateID
						,PostEventBatchProcedure
					)
					select
						EventID = e.EventID
						,MaxIncUpdateID = max(te.ID)
						,PostEventBatchProcedure = e.PostEventBatchProcedure
					from
						#EventIncUpdate te
							inner join app.IncUpdate_EventConfiguration e on
								e.EventID = te.EventID
					where
						e.IsDisabled = 0
					group by
						e.EventID
						,e.PostEventBatchProcedure
						,e.EventOrder
					order by
						e.EventOrder
						,e.EventID

					set @TriggerOrderIteratorMax = @@ROWCOUNT
					set @TriggerOrderIterator = 1

					-- I rätt ordning per event.
					--	* Beräkna
					--  * Processa
					--
					while (@TriggerOrderIterator <= @TriggerOrderIteratorMax)
						begin
							--
							-- Hämta info om aktuellt event
							--
							select
								@EventID = e.EventID
								,@MaxIncUpdateID = t.MaxIncUpdateID
								,@CalcProc = e.CalculateProcedure
								,@PostEventBatchProcedure = e.PostEventBatchProcedure
							from
								#TriggeredEvents t
									inner join app.IncUpdate_EventConfiguration e on
										e.EventID = t.EventID
							where
								t.TriggerOrder = @TriggerOrderIterator
								and e.IsDisabled = 0
							--
							-- Fyll temptabell 
							--
							insert into #IncUpdate(ID)
							select ID from #EventIncUpdate 
							where EventID = @EventID

							if (@CalcProc) <> ''
								begin							
									exec [app].[IncUpdate_EventHandler_ExecEventProc]
										@ProcName = @CalcProc
										,@Type = @Type
										,@ParamList = @ParamList
										,@ParentEventID = @EventIDStack
										,@MaxIncUpdateID = @MaxIncUpdateID
										,@EventID = @EventID
									
									--
									-- Synka eventuella förändringar i #IncUpdate tillbaka till #EventIncUpdate
									--
									;with TargetFilter as
									(
										select
											*
										from
											[#EventIncUpdate]
										where
											EventID = @EventID
									)
									merge TargetFilter as dest
									using [#IncUpdate] as src on
										src.[ID] = dest.[ID]
									when not matched by target then
										insert([EventID], [ID])
										values(@EventID, src.[ID])
									when not matched by source then
										delete
									;
								end

							--
							-- Hantera eventuell processning kopplad till detta event.
							--
							exec [app].[IncUpdate_EventHandler_Process]
								@EventID = @EventID
								,@MaxIncUpdateID = @MaxIncUpdateID
								,@Type = @Type
								,@ParamList = @ParamList
								,@ParentEventID = @EventIDStack
  
  
							truncate table #IncUpdate

							set @TriggerOrderIterator = @TriggerOrderIterator + 1
						end


				end


            select @EventPrio = MAX(EventPrio) from [app].IncUpdate_EventConfiguration where EventPrio < @EventPrio and JobID = @JobID and IsDisabled = 0
        end
  
  
          
        if exists(select 1 from #TriggeredEvents)
            begin
                --
                -- Ska event som har triggats trigga ytterligare event?
                --
                select distinct
                    te.EventID
                    ,te.CalculateProcedure
                    --,te.ProcessProcedure
                    ,te.PostEventBatchProcedure
					,te.EventOrder
                into #TriggerOnEventEvents
                from
                    #TriggeredEvents e
                        inner join [app].IncUpdate_EventConfiguration_TriggerOnEvent t on
                            t.When_IncUpdateEventID = e.EventID
                        inner join [app].IncUpdate_EventConfiguration te on
                            te.EventID = t.Trigger_IncUpdateEventID
                where
                    te.EventTriggerTypeID = 'TriggerOnEvent'
                    and te.JobID = @JobID
					and te.IsDisabled = 0
  
                if @@ROWCOUNT > 0
                    begin
                        while exists(select 1 from #TriggerOnEventEvents)
                            begin
                                select top 1
                                    @EventID = e.EventID
                                    ,@CalcProc = e.CalculateProcedure
                                    ,@PostEventBatchProcedure = e.PostEventBatchProcedure
                                    ,@MaxIncUpdateID = null                                      
                                from
                                    #TriggerOnEventEvents e
								order by
									e.EventOrder
  
                                if (@CalcProc) <> ''
                                    begin
                                        exec [app].[IncUpdate_EventHandler_ExecEventProc]
                                            @ProcName = @CalcProc
                                            ,@Type = @Type
                                            ,@ParamList = @ParamList
                                            ,@ParentEventID = @EventIDStack
                                            ,@MaxIncUpdateID = @MaxIncUpdateID
                                            ,@EventID = @EventID
  
                                        --
                                        -- Spara Eventets IncUpdate ID:n till steg för rensning av IncUpdate och processning
                                        --
                                        insert into #EventIncUpdate
                                        (
                                            EventID
                                            ,ID
                                        )
                                        select
                                            @EventID
                                            ,ID
                                        from
                                            #IncUpdate
                                          
                                    end
  
                                select @MaxIncUpdateID = MAX(ID) from #IncUpdate
  
                                exec [app].[IncUpdate_EventHandler_Process]
                                    @EventID = @EventID
                                    ,@MaxIncUpdateID = @MaxIncUpdateID
                                    ,@Type = @Type
                                    ,@ParamList = @ParamList
                                    ,@ParentEventID = @EventIDStack
  
                          
  
                              
                                truncate table #IncUpdate
                                  
                                delete from #TriggerOnEventEvents where EventID = @EventID
                            end
                    end
  
                select @EventID = MIN(EventID) from #TriggeredEvents where PostEventBatchProcedure <> ''
                while @EventID is not null
                    begin
                          
                        select
                            @PostEventBatchProcedure = te.PostEventBatchProcedure
                            ,@MaxIncUpdateID = te.MaxIncUpdateID
                        from
                            #TriggeredEvents te
                        where
                            te.EventID = @EventID
						truncate table #IncUpdate 
                        insert into #IncUpdate
                        (
                            ID
                        )
                        select
                            ID
                        from
                            #EventIncUpdate
                        where
                            EventID = @EventID
						exec app.IncUpdate_EventHandler_ExecEventProc 
									 @ProcName = @PostEventBatchProcedure
									,@Type = @Type
									,@ParamList = @ParamList
									,@ParentEventID = @EventIDStack
									,@MaxIncUpdateID = @MaxIncUpdateID
									,@EventID = @EventID

                        select @EventID = MIN(EventID) from #TriggeredEvents where EventID > @EventID and PostEventBatchProcedure <> ''
                    end
  
                --
                -- Rensa och fixa i triggertabeller för att markera saker som hanterat.
                --
                select @DynSQL =
                    isnull
                    (
                        (
                            select N'
                                update f set
                                    IncUpdate = 0
                                from
                                    ' + e.TriggerTable + N' f
                                        inner join #EventIncUpdate inc on
                                            inc.ID = f.' + isnull(e.TriggerIdColumnName, N'ID') + N'
                                where
                                    inc.EventID = ' + CAST(e.EventID as nvarchar(max)) + N'
                                    and f.IncUpdate = 1;
                                '
                            from
                                #TriggeredEvents te
                                    inner join [app].IncUpdate_EventConfiguration e on
                                        e.EventID = te.EventID                                
                            where
                                e.EventTriggerTypeID in ('IncUpdate')
                                and e.TriggerTable <> ''
								and e.IsDisabled = 0
                            FOR XML PATH, TYPE
                        ).value(N'.[1]', N'nvarchar(max)')
                        ,N''
                    )
                    +
                    isnull
                    (
                        (
                            select N'
                                delete from f
                                from
                                    ' + e.TriggerTable + N' f
                                        inner join #EventIncUpdate inc on
                                            inc.ID = f.' + isnull(e.TriggerIdColumnName, N'ID') + N'
                                where
                                    inc.EventID = ' + CAST(e.EventID as nvarchar(max)) + N';
                                '
                            from
                                #TriggeredEvents te
                                    inner join [app].IncUpdate_EventConfiguration e on
                                        e.EventID = te.EventID
                            where
                                e.EventTriggerTypeID in ('RowsExists')
                                and e.TriggerTable <> ''
								and e.IsDisabled = 0
                            FOR XML PATH, TYPE
                        ).value(N'.[1]', N'nvarchar(max)')
                        ,N''
                    )
                if (@DynSQL) <> ''
                    begin
                        begin try
							exec (@DynSQL)
						end try
						begin catch
							select @ErrorMessage = app.GetErrorMessage();
							raiserror('Error executing dynamic SQL "%s" for event id %i, Error: %s', 16, 10
								,@DynSQL
								,@EventID							
								,@ErrorMessage);
						end catch
                    end
            end
      
  
  
    exec app.LogEventStop @EventIDStack = @EventIDStack out
    --------------------------------------------------------------------------
    -- Stop
    --------------------------------------------------------------------------
end try
begin catch
    --
    -- Roll back any transactions and log errors
    --
    if @TranCount = 0 and @@trancount > 0 rollback tran
    exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
    exec app.ReThrowError
end catch
GO
